-- Replace the legacy sector-based package catalog with one outcome-based Rawaj package system.
alter table public.packages
  add column if not exists solution_key text,
  add column if not exists audience_ar text,
  add column if not exists tiers jsonb not null default '[]'::jsonb;

delete from public.packages;

