  id,title_ar,title_en,slug,tagline_ar,description_ar,hero_image,badge,featured,
  service_ids,benefits_ar,sort_order,sector_key,target_sector_ar,ideal_for_ar,
  turnaround_time_ar,items_breakdown,key_advantages_ar,is_active,solution_key,
  audience_ar,tiers
)
